describe('Focus Indicators on Interactive Elements', () => {
  beforeEach(() => {
    cy.visit('/interactive-elements');
  });

  it('should display focus indicators on all interactive elements when focused', () => {
    // Verify focus indicator is visible on button
    cy.get('[data-testid="submit-button"]').focus();
    cy.get('[data-testid="submit-button"]').should('have.class', 'focus-visible');
    cy.get('[data-testid="submit-button"]').should('be.visible');

    // Verify focus indicator is visible on link
    cy.get('[data-testid="nav-link"]').focus();
    cy.get('[data-testid="nav-link"]').should('have.class', 'focus-visible');
    cy.get('[data-testid="nav-link"]').should('be.visible');

    // Verify focus indicator is visible on input field
    cy.get('[data-testid="search-input"]').focus();
    cy.get('[data-testid="search-input"]').should('have.class', 'focus-visible');
    cy.get('[data-testid="search-input"]').should('be.visible');

    // Verify focus indicator is visible on select dropdown
    cy.get('[data-testid="dropdown-select"]').focus();
    cy.get('[data-testid="dropdown-select"]').should('have.class', 'focus-visible');
    cy.get('[data-testid="dropdown-select"]').should('be.visible');

    // Verify focus indicator is visible on checkbox
    cy.get('[data-testid="checkbox-option"]').focus();
    cy.get('[data-testid="checkbox-option"]').should('have.class', 'focus-visible');
    cy.get('[data-testid="checkbox-option"]').should('be.visible');
  });

  it('should remove focus indicator when element loses focus', () => {
    // Focus on button and verify indicator is visible
    cy.get('[data-testid="submit-button"]').focus();
    cy.get('[data-testid="submit-button"]').should('have.class', 'focus-visible');

    // Tab to next element to remove focus from button
    cy.get('[data-testid="nav-link"]').focus();
    cy.get('[data-testid="submit-button"]').should('not.have.class', 'focus-visible');

    // Focus on input and verify indicator is visible
    cy.get('[data-testid="search-input"]').focus();
    cy.get('[data-testid="search-input"]').should('have.class', 'focus-visible');

    // Tab to next element to remove focus from input
    cy.get('[data-testid="dropdown-select"]').focus();
    cy.get('[data-testid="search-input"]').should('not.have.class', 'focus-visible');

    // Verify focus indicator is not present on non-interactive elements
    cy.get('[data-testid="page-title"]').should('not.have.class', 'focus-visible');
  });
});
